def find_most_common(text):
    # Split the text into individual words
    words = text.split()

    # Create a dictionary to store word frequencies
    freqs = {}

    # Iterate over each word and update its frequency
    for word in words:
        if word in freqs:
            freqs[word] += 1
        else:
            freqs[word] = 1

    # Sort the dictionary by value (frequency)
    sorted_freqs = sorted(freqs.items(), key=lambda x: x[1], reverse=True)

    # Return the top N most common words and their frequencies
    return sorted_freqs[:5],1,AI,llama-chat,medium,code

