def three_closest(a, b, c):
    """
    Find three closest elements from three sorted arrays.
    """
    # sort the arrays
    a = sorted(a)
    b = sorted(b)
    c = sorted(c)

    # find the closest elements
    closest_a = a[0]
    closest_b = b[0]
    closest_c = c[0]

    # find the closest elements
    for i in range(1, len(a)):
        if abs(a[i] - closest_a) < abs(a[i - 1] - closest_a):
            closest_a = a[i]

    for i in range(1, len(b)):
        if abs(b[i] - closest_b) < abs(b[i - 1] - closest_b):
            closest_b = b[i]

    for i in range(1, len(c)):
        if abs(c[i] - closest_c) < abs(c[i - 1] - closest_c):
            closest_c = c[i]

    return closest_a, closest_b, closest_c,1,AI,mpt,medium,code

