def odd_occurrences(arr):
    # Create a dictionary to count the occurrences of each element
    count = {}
    for num in arr:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    # Initialize an empty list to store the elements with odd occurrences
    result = []

    # Iterate through the dictionary and append the elements with odd occurrences to the result list
    for num in count:
        if count[num] % 2!= 0:
            result.append(num)

    return result,1,AI,mpt-chat,medium,code

def min_jumps(arr, n):
	jumps = [0 for i in range(n)]
	if (n == 0) or (arr[0] == 0):
		return float('inf')
	jumps[0] = 0
	for i in range(1, n):
		jumps[i] = float('inf')
		for j in range(i):
			if (i <= j + arr[j]) and (jumps[j] != float('inf')):
				jumps[i] = min(jumps[i], jumps[j] + 1)
				break
	return jumps[n-1],0,Human,human,medium,code

def find_index(arr, target):
    low = 0
    high = len(arr) - 1

    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

