def num_subsequences(arr, k):
    """
    Return the number of subsequences of arr having product smaller than k.
    """
    n = len(arr)
    dp = [0] * (k + 1)

    for i in range(n):
        for j in range(k + 1):
            if arr[i] > j:
                dp[j] += dp[j - arr[i]]
            else:
                dp[j] += dp[j - arr[i]] + 1

    return dp[k],1,AI,llama-chat,medium,code

