def min_path_sum(triangle):
    rows = len(triangle)
    cols = len(triangle[0])
    dp = [[0] * (cols+1) for _ in range(rows+1)]

    for i in range(1, rows+1):
        for j in range(1, cols+1):
            if i == 1 or j == 1:
                dp[i][j] = triangle[i-1][j-1]
