def validate_gregorian_date(year, month, day):
    """
    Returns True if the given date is valid, False otherwise.
    """
    # Check year range
    if not (1 <= year <= 9999):
        return False

    # Check month range
    if not (1 <= month <= 12):
        return False

    # Check day range
    if not (1 <= day <= 31):
        return False

    # Check for invalid dates (e.g. February 30)
    if month == 2 and day > 28:
