def min_swaps(s):
    # Initialize a stack to keep track of the brackets
    stack = []

    # Iterate through the string and perform the following operations:
    # 1. If the current character is an opening bracket, push it onto the stack.
    # 2. If the current character is a closing bracket, pop the matching opening bracket from the stack.
    # 3. If the stack is not empty and the current character is a closing bracket, swap the top two elements of the stack.
    for i, c in enumerate(s):
        if c == '(':
            stack.append(i)
        elif c == ')':
            if stack:
                stack.pop()
            else:
                # If we reach a closing bracket without a matching opening bracket,
                # it means the string is not balanced, so return -1
                return -1
        elif stack and c == '(':
            # Swap the top two elements of the stack
            stack[0], stack[-1] = stack[-1], stack[0]

    # If the stack is empty, the string is balanced, so return 0
    return len(stack)

