# Helper function to find the sum of proper divisors of a number
def sum_of_proper_divisors(n):
    proper_divisors = []
    i = 2
    while i * i <= n:
        if n % i == 0:
            proper_divisors.append(i)
            proper_divisors.append(n // i)
        i += 1
    if n > 1:
        proper_divisors.append(n)
    return sum(proper_divisors),1,AI,mpt-chat,medium,code

