def is_even_divisor_count(n):
    """
    Check whether the count of divisors of n is even or odd.
    """
    divisors = [1]
    for i in range(2, int(n**0.5)+1):
        if n % i == 0:
            divisors.append(i)
            if i!= n//i:
                divisors.append(n//i)
    return len(divisors) % 2 == 0,1,AI,mpt,short,code

