def minPathSum(triangle):
    """
    :type triangle: List[List[int]]
    :rtype: int
    """
    if not triangle:
        return 0
    if len(triangle) == 1:
        return triangle[0][0]
    if len(triangle) == 2:
        return min(triangle[0][0], triangle[1][0])

    # find the minimum of the first row
    min_row = triangle[0][0]
    for i in range(1, len(triangle[0])):
        min_row = min(min_row, triangle[0][i])

    # find the minimum of the first column
    min_col = triangle[0][0]
    for i in range(1, len(triangle)):
        min_col = min(min_col, triangle[i][0])

    # find the minimum of the first diagonal
    min_diag = triangle[0][0]
    for i in range(1, len(triangle)):
        min_diag = min(min_diag, triangle[i][i])

    # find the minimum of the second diagonal
    min_diag = triangle[0][0]
    for i in range(1, len(triangle)):
        min_diag = min(min_diag, triangle[i][len(triangle[0]) - i - 1])

    return min(min_row, min_col, min_diag),1,AI,mpt,medium,code

