def min_swaps(s):
    stack = []
    for c in s:
        if c == '(':
            stack.append(c)
        elif c == ')':
            if not stack:
                return -1
            elif stack[-1] == '(':
                stack.pop()
            else:
                return -1
        else:
            return -1
    return len(stack),1,AI,mpt,short,code

