def min_remove(arr, k):
    if len(arr) == 0:
        return 0
    if len(arr) == 1:
        return 0 if arr[0] <= k else 1
    if len(arr) == 2:
        return 0 if arr[0] <= arr[1] <= k else 1
    if arr[0] <= k:
        return 1
    if arr[len(arr) - 1] <= k:
        return len(arr) - 1
    if arr[0] > arr[len(arr) - 1]:
        return min_remove(arr[1:], k)
    if arr[0] <= arr[1]:
        return min_remove(arr[1:], k) + 1
    if arr[0] > arr[1]:
        return min_remove(arr[0:2], k) + 1,1,AI,mpt,medium,code

