def spiral_matrix(n):
    """
    Generate a square matrix filled with elements from 1 to n raised to the power of 2 in spiral order.
    """
    if n < 1:
        return []
    matrix = [[0 for _ in range(n)] for _ in range(n)]
    i, j = 0, 0
    while i < n and j < n:
        for _ in range(n - i - j):
            matrix[i][j] = 1
            j += 1
        for _ in range(i + j, n):
            matrix[i][j] = 2
            i += 1
        for _ in range(i, n - j):
            matrix[i][j] = 4
            i += 1
        for _ in range(j, n):
            matrix[i][j] = 8
            j += 1
    return matrix,1,AI,mpt,medium,code

