def flatten_list(list1):
    result_list = []
    if not list1: return result_list
    stack = [list(list1)]
    while stack:
        c_num = stack.pop()
        next = c_num.pop()
        if c_num: stack.append(c_num)
        if isinstance(next, list):
            if next: stack.append(list(next))
        else: result_list.append(next)
    result_list.reverse()
    return result_list,0,Human,human,short,code

def counting_sort(arr):
    # Calculate the number of elements in each bucket
    buckets = [0] * (max(arr) + 1)
    for element in arr:
        buckets[element] += 1

    # Update the counts for each bucket
    for i in range(len(buckets)):
        buckets[i] -= buckets[i-1] if i > 0 else 0

    # Sort the array using the counts
    sorted_array = []
    for i in range(len(arr)):
        while buckets[arr[i]] > 0:
            sorted_array.append(arr[i])
            buckets[arr[i]] -= 1
    return sorted_array,1,AI,llama-chat,medium,code

