def count_distinct_power_of_prime_factor(n):
    factors = []
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    for i in range(3, int(n**0.5)+1, 2):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 2:
        factors.append(n)
    prime_factors = set(factors)
    count = 0
    for factor in prime_factors:
        count += len(str(factor)**n)
    return count,1,AI,mpt-chat,medium,code

