def find_smallest_range(arrays):
    min_values = [float('inf')] * len(arrays)
    max_values = [float('-inf')] * len(arrays)

    for i, array in enumerate(arrays):
        for value in array:
            if value < min_values[i]:
                min_values[i] = value
            if value > max_values[i]:
                max_values[i] = value

    smallest_range = float('inf')
    for i in range(len(arrays)):
        range_i = max_values[i] - min_values[i]
        smallest_range = min(smallest_range, range_i)

    return smallest_range,1,AI,mpt-chat,medium,code

