def find_insertion_point(sorted_list, value):
    """
    Find the insertion point for a value in a sorted list.
    """
    if not sorted_list:
        return 0
    if sorted_list[0] == value:
        return 0
    if sorted_list[-1] == value:
        return len(sorted_list) - 1
    if sorted_list[0] > value:
        return 0
    if sorted_list[-1] < value:
        return len(sorted_list) - 1
    for i in range(len(sorted_list)):
        if sorted_list[i] == value:
            return i
        if sorted_list[i] > value:
            return i
    return len(sorted_list),1,AI,mpt,medium,code

