def longest_bitonic_subsequence(arr):
    n = len(arr)
    if n <= 1:
        return arr

    # Find the maximum bitonic subsequence
    max_len = 1
    for i in range(1, n):
        max_len = max(max_len, find_bitonic_subsequence_len(arr, i))

    # Find the longest bitonic subsequence
    result = []
    for i in range(n):
        len_curr = find_bitonic_subsequence_len(arr, i)
        if len_curr > max_len:
            result = find_bitonic_subsequence(arr, i)
            max_len = len_curr

    return result

