def heapify_max(lst, i, n):
    largest = i
    l = 2*i + 1
    r = 2*i + 2
    if l < n and lst[l] > lst[largest]:
        largest = l
    if r < n and lst[r] > lst[largest]:
        largest = r
    if largest!= i:
        lst[i], lst[largest] = lst[largest], lst[i]
        heapify_max(lst, largest, n),1,AI,mpt,medium,code

