def max_average_path(matrix):
    if not matrix or not matrix[0]:
        return 0

    n = len(matrix)
    max_sum = 0
    max_path = []

    for i in range(n):
        row_sum = sum(matrix[i])
        max_sum = max(max_sum, row_sum)
        max_path += [row_sum]

        for j in range(n):
            if i == j:
                continue
            col_sum = sum(matrix[j])
            max_path[i] += col_sum

    max_avg = max_sum / n
    for i in range(1, n):
        max_avg = max(max_avg, max_path[i] / (i + 1))

    return max_avg,1,AI,mpt-chat,medium,code

