def build_heap(arr):
    n = len(arr)
    for i in range((n // 2) - 1, -1, -1):
        sink(arr, i, n)
    return arr

def sink(arr, i, n):
    largest = i
    left = 2 * i + 1
    right = 2 * i + 2
    if left < n and arr[left] > arr[largest]:
        largest = left
    elif right < n and arr[right] > arr[largest]:
        largest = right
    if i != largest:
        arr[i], arr[largest] = arr[largest], arr[i]
        sink(arr, largest, n),1,AI,llama-chat,medium,code

