def max_product(nums):
    """
    :type nums: List[int]
    :rtype: int
    """
    if len(nums) == 0:
        return 0
    if len(nums) == 1:
        return nums[0]
    if len(nums) == 2:
        return max(nums[0] * nums[1], nums[1] * nums[0])

    max_product = nums[0] * nums[1]
    max_num = nums[0]
    min_num = nums[1]

    for i in range(2, len(nums)):
        num = nums[i]
        if num * max_num < max_product:
            max_product = num * max_num
            max_num = num
        elif num * min_num > max_product:
            max_product = num * min_num
            min_num = num
        else:
            pass
    return max_product,1,AI,mpt,medium,code

