def isIsomorphic(s1, s2):
    if len(s1)!= len(s2):
        return False

    d1 = {}
    d2 = {}

    for i in range(len(s1)):
        if s1[i] not in d1:
            d1[s1[i]] = s2[i]
        else:
            if d1[s1[i]]!= s2[i]:
                return False

        if s2[i] not in d2:
