def min_path_sum(triangle):
    row = len(triangle) - 1
    col = len(triangle[0]) - 1

    while row >= 0:
        min_val = triangle[row][col]

        if col - 1 >= 0:
            min_val = min(min_val, triangle[row][col - 1])

        if row - 1 >= 0 and col + 1 < len(triangle[0]):
            min_val = min(min_val, triangle[row - 1][col + 1])

        triangle[row][col] = min_val
        row -= 1
        col -= 1

    return triangle[0][0],1,AI,mpt-chat,medium,code

