def sum_of_odd_factors(n):
    """
    Returns the sum of all odd factors of n.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n % 2 == 0:
        return sum_of_odd_factors(n // 2)
    return n + sum_of_odd_factors(n - 1),1,AI,mpt,short,code

