def smallest_multiple(n):
    factors = []
    for i in range(1, n+1):
        for j in range(i, n+1):
            if i % j == 0:
                factors.append(j)
    lcm = 1
    for factor in factors:
        lcm = (lcm * factor) // __gcd(factor, lcm)
    return lcm * n

