def min_swaps(s1, s2):
    if len(s1)!= len(s2):
        return -1
    if s1 == s2:
        return 0

    # count the number of different characters
    diff = 0
    for i in range(len(s1)):
        if s1[i]!= s2[i]:
            diff += 1

    # if there are no different characters, then the strings are equal
    if diff == 0:
        return 0

    # if there are different characters, then we need to swap them
    # to make the strings equal
    return diff,1,AI,mpt,medium,code

