def most_common_elements(text):
    # Convert the text to a list of individual characters
    chars = list(text)

    # Create a dictionary to store the character counts
    char_counts = {}

    # Iterate over the characters and update the count for each character
    for char in chars:
        if char in char_counts:
            char_counts[char] += 1
        else:
            char_counts[char] = 1

    # Sort the character counts in descending order
    sorted_counts = sorted(char_counts.items(), key=lambda x: x[1], reverse=True)

    # Return the most common characters and their counts
    return sorted_counts,1,AI,llama-chat,medium,code

def sum_of_subarray_products(arr):
    n = len(arr)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(i, n + 1):
            dp[i][j] = arr[i] * (j - i + 1) + dp[i - 1][j - 1]

