def max_sum_non_adjacent(n):
    # Initialize a 2D array to store the sums of non-adjacent elements
    sums = [[0] * (n+1) for _ in range(2)]

    # Populate the sums array
    for i in range(2):
        for j in range(n+1):
            if i == 0 or j == 0:
                sums[i][j] = 0
            else:
                sums[i][j] = sums[i-1][j-1] + sums[i-1][j] + sums[i][j-1] - sums[i-1][j-1]

    # Find the maximum sum
    max_sum = None
    for i in range(2):
        for j in range(n+1):
            if max_sum is None or sums[i][j] > max_sum:
                max_sum = sums[i][j]

    return max_sum

