def is_valid_date(date):
    """
    Check if a date is valid.
    :param date: a string representing a date
    :return: True if the date is valid, False otherwise
    """
    try:
        date = date.split()
        if len(date)!= 3:
            return False
        day, month, year = date
        if len(day)!= 2:
            return False
        if len(month)!= 2:
            return False
        if len(year)!= 4:
            return False
        if int(day) > 31:
            return False
        if int(month) > 12:
            return False
        if int(year) < 100:
            return False
        if int(year) % 4 == 0 and int(year) % 100!= 0 or int(year) % 400 == 0:
            return False
        return True
    except ValueError:
        return False,1,AI,mpt,medium,code

