def longest_bitonic(arr):
    n = len(arr)
    dp = [[0] * (n + 1) for _ in range(2)]

    for i in range(1, n + 1):
        for j in range(i, n + 1):
            if arr[j - 1] == arr[j]:
                dp[0][j] = max(dp[0][j], dp[0][j - 1] + 1)
                dp[1][j] = max(dp[1][j], dp[1][j - 1] + 1)
            else:
                dp[0][j] = max(dp[0][j], dp[0][j - 1])
                dp[1][j] = max(dp[1][j], dp[1][j - 1])

    return max(dp[0][n], dp[1][n]),1,AI,llama-chat,medium,code

