def toggle_case(str):
    """
    Toggles the case of each character in the input string.

    Args:
        str (str): The string whose case should be toggled.

    Returns:
        str: The string with its case toggled.
    """
    result = ""
    for c in str:
        if c.isalpha():
            if c.islower():
                result += c.swapcase()
            else:
                result += c.lower()
        else:
            result += c
    return result,1,AI,llama-chat,medium,code

