def num_subsequences(arr, k):
    n = len(arr)
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(k + 1):
            if arr[i] > j:
                dp[i + 1][j] = dp[i][j - arr[i]]
            else:
                dp[i + 1][j] = dp[i][j] + 1

    return dp[n][k],1,AI,llama-chat,medium,code

