def find_min(arr):
    if len(arr) == 0:
        return None
    if len(arr) == 1:
        return arr[0]
    if len(arr) == 2:
        return min(arr)
    if arr[0] > arr[1]:
        return arr[0]
    if arr[len(arr) - 1] > arr[len(arr) - 2]:
        return arr[len(arr) - 1]
    return min(arr[1:len(arr) - 1]),1,AI,mpt,medium,code

