# Helper function to generate bounded ranges for a given set of integers
def bounded_ranges(integers):
    ranges = []
    current_start = None
    for i in sorted(integers):
        if not current_start or i - current_start > 1:
            ranges.append((current_start, i])
            current_start = i
    return ranges,1,AI,llama-chat,medium,code

