    if len(arr) == 0:
        return 0
    if len(arr) == 1:
        return 1 if arr[0] < k else 0
    if arr[0] < k:
        return 1 + subsequences(arr[1:], k)
    return subsequences(arr[1:], k),1,AI,mpt,short,code

def odd_days_in_year(year):
    days = [1, 3, 5, 7, 8, 10, 12]
    odd_days = 0
    for month in range(1, 13):
        days_in_month = 28
        if month == 2:
            days_in_month = (year % 4 == 0 and year % 100!= 0) or year % 400 == 0 else 29
        for day in range(1, days_in_month + 1):
