    else : 
        return ("Odd"),0,Human,human,short,code

def coin_change(amount, coins):
    dp = [0] * (amount + 1)
    for coin in coins:
        for i in range(coin, amount + 1):
            dp[i] = max(dp[i], dp[i - coin] + 1)
    return dp[amount] if dp[amount]!= 0 else -1

