def counting_sort(arr):
    # Initialize a dictionary to count the number of occurrences of each element
    counts = {}
    for ele in arr:
        if ele in counts:
            counts[ele] += 1
        else:
            counts[ele] = 1

    # Initialize an empty list to store the sorted array
    sorted_arr = []

    # Iterate over the counts and add elements to the sorted array
    for ele, count in counts.items():
        for _ in range(count):
            sorted_arr.append(ele)

    return sorted_arr,1,AI,llama-chat,medium,code

