import math
import sys
def sd_calc(data):
    n = len(data)
    if n <= 1:
        return 0.0
    mean, sd = avg_calc(data), 0.0
    for el in data:
        sd += (float(el) - mean)**2
    sd = math.sqrt(sd / float(n-1))
    return sd
def avg_calc(ls):
    n, mean = len(ls), 0.0
    if n <= 1:
        return ls[0]
    for el in ls:
        mean = mean + float(el)
    mean = mean / float(n)
    return mean,0,Human,human,medium,code

def create_magic_square(side_length):
    # Create a list of lists with side_length**2 elements
    square = [[0] * side_length for _ in range(side_length)]

    # Fill the diagonal from top left to bottom right
    for i in range(side_length):
        square[i][i] = i + 1

    # Fill the rest of the elements
    for i in range(side_length):
        for j in range(side_length):
            if i == j:
                square[i][j] = side_length - i
            else:
                square[i][j] = (side_length * (i + j) + i - j) % side_length

    return square,1,AI,mpt-chat,medium,code

def heapify(arr):
    n = len(arr)
    for i in range(n//2, n):
        heapify_down(arr, i)
    return arr

def heapify_down(arr, i):
    largest = i
    left = 2 * i + 1
    right = 2 * i + 2
    if left < len(arr) and arr[left] > arr[largest]:
        largest = left
    if right < len(arr) and arr[right] > arr[largest]:
        largest = right
    if largest != i:
        arr[i], arr[largest] = arr[largest], arr[i]
        heapify_down(arr, largest),1,AI,llama-chat,medium,code

