def binomial_probability(n, k, p):
    """
    Compute the binomial probability of k successes in n trials,
    where each trial has probability p of success.
    """
    if k < 0 or k > n:
        raise ValueError("k must be between 0 and n")
    if p < 0 or p > 1:
        raise ValueError("p must be between 0 and 1")
    if n == 0:
        return 0
    if n == 1:
        return p
    if k == 0 or k == n:
        return 1
    return (1 - p) ** (n - k) * p ** k / math.factorial(n),1,AI,mpt,medium,code

def min_squares(n):
    # Base case: If n is 0, the minimum number of squares is 0
    if n == 0:
        return 0

    # Otherwise, find the square root of n and round up to the nearest integer
    square_root = int(n ** 0.5)
    squares = [i ** 2 for i in range(square_root + 1)]

    # Find the first square that is greater than or equal to n
    for square in squares:
        if square >= n:
            return squares.index(square) + 1

    # If no square is greater than or equal to n, return the last square
    return squares.index(squares[-1]) + 1,1,AI,llama-chat,medium,code

