def max_average_path(matrix):
    """
    Find a path with the maximum average over all existing paths in the given square matrix.
    """
    # Initialize the maximum average and the corresponding path
    max_average = -float('inf')
    max_path = []

    # Iterate over all possible paths in the matrix
    for row in range(len(matrix)):
        for col in range(len(matrix[row])):
            # Compute the average of the current path
            current_average = 0
            for i in range(row, row + 2):
                for j in range(col, col + 2):
                    if i >= 0 and i < len(matrix) and j >= 0 and j < len(matrix[i]):
                        current_average += matrix[i][j]
            current_average /= 4

            # Check if the current path has a higher average than the maximum average
            if current_average > max_average:
                max_average = current_average
                max_path = [row, col]

    return max_path,1,AI,llama-chat,medium,code

