def sum_of_common_divisors(a, b):
    """
    Find the sum of common divisors of two given numbers.
    """
    if a == 0 or b == 0:
        return 0
    if a == b:
        return a
    if a > b:
        a, b = b, a
    for i in range(1, a + 1):
        if a % i == 0 and b % i == 0:
            return i
    return 0,1,AI,mpt,medium,code

