def median_of_two_arrays(a, b):
    # Check if the arrays have the same length
    if len(a) != len(b):
        raise ValueError("Arrays must have the same length")

    # Find the middle index of the combined array
    mid = len(a) // 2

    # If the length of the arrays is odd, return the middle element of the combined array
    if len(a) % 2 == 1:
        return a[mid]

    # If the length of the arrays is even, return the average of the two middle elements
    else:
        return (a[mid - 1] + b[mid - 1]) / 2,1,AI,llama-chat,medium,code

