def prev_palindrome(n):
    """
    Find the previous palindrome of a specified number.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n % 10 == 0:
        return prev_palindrome(n // 10)
    if n % 10 == 1:
        return prev_palindrome(n // 10) + 1
    if n % 10 == 2:
        return prev_palindrome(n // 10) + 2
