def count_subsequences(arr, k):
    n = len(arr)
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(k + 1):
            if j == 0:
                dp[i][j] = dp[i - 1][j]
            elif arr[i - 1] < j:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j] + dp[i - 1][j - arr[i - 1]]

    return dp[n][k],1,AI,mpt-chat,medium,code

def count_same_pair(list1, list2, list3):
    seen = set()
    count = 0
    for a in list1:
        for b in list2:
            if a == b:
                seen.add((a, b))
                count += 1
    for c in list3:
        if (c,) in seen:
            count += 1
    return count,1,AI,llama-chat,short,code

def ncr_mod(n, r, p):
    if r < 0:
        r += p
    result = 1
    for i in range(1, r+1):
        result = (result * (n-i+1)) % p
    return result

